@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>@(Course?.Title ?? "Course Not Found")</PageTitle>

@if (Course is not null)
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            <li class="breadcrumb-item active">@Course.Code</li>
        </ol>
    </nav>

    <h1>@Course.Code — @Course.Title</h1>

    <div class="row mt-4">
        <div class="col-md-8">
            <h3>Description</h3>
            <p>@Course.Description</p>

            <h3 class="mt-4">Schedule</h3>
            <p><strong>@Course.Schedule</strong></p>

            <h3 class="mt-4">Instructor</h3>
            <p><strong>@Course.InstructorName</strong></p>
            <p>@Course.InstructorBio</p>
        </div>
        <div class="col-md-4">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">Course Info</h5>
                    <ul class="list-unstyled">
                        <li><strong>Code:</strong> @Course.Code</li>
                        <li><strong>Credits:</strong> @Course.Credits</li>
                        <li><strong>Department:</strong> @Course.DepartmentName</li>
                    </ul>
                    <a href="enroll?courseId=@Course.Id" class="btn btn-success w-100">Enroll in this Course</a>
                </div>
            </div>
        </div>
    </div>
}
else
{
    <h1>Course Not Found</h1>
    <p>The requested course could not be found. <a href="courses">Browse all courses</a>.</p>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Course? Course { get; set; }

    protected override void OnInitialized()
    {
        Course = CatalogService.GetCourseById(Id);
    }
}

@page "/departments"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>Departments</PageTitle>

<h1>Departments</h1>

<div class="row">
    @foreach (var dept in Departments)
    {
        <div class="col-md-6 mb-4">
            <div class="card">
                <div class="card-body">
                    <h4 class="card-title">@dept.Name (@dept.Code)</h4>
                    <p class="card-text">@dept.Description</p>
                    <a href="departments/@dept.Id" class="btn btn-primary">View Courses</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private List<Department> Departments { get; set; } = new();

    protected override void OnInitialized()
    {
        Departments = CatalogService.GetAllDepartments();
    }
}

@page "/departments/{Id:int}"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>@(Department?.Name ?? "Department Not Found")</PageTitle>

@if (Department is not null)
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="departments">Departments</a></li>
            <li class="breadcrumb-item active">@Department.Name</li>
        </ol>
    </nav>

    <h1>@Department.Name</h1>
    <p class="lead">@Department.Description</p>

    <h2 class="mt-4">Courses</h2>
    @if (Courses.Any())
    {
        <div class="list-group">
            @foreach (var course in Courses)
            {
                <a href="courses/@course.Id" class="list-group-item list-group-item-action">
                    <div class="d-flex w-100 justify-content-between">
                        <h5 class="mb-1">@course.Code — @course.Title</h5>
                        <small>@course.Credits credits</small>
                    </div>
                    <p class="mb-1">@course.Schedule</p>
                    <small class="text-muted">Instructor: @course.InstructorName</small>
                </a>
            }
        </div>
    }
    else
    {
        <p class="text-muted">No courses are currently listed for this department.</p>
    }
}
else
{
    <h1>Department Not Found</h1>
    <p>The requested department could not be found. <a href="departments">Browse all departments</a>.</p>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private Department? Department { get; set; }
    private List<Course> Courses { get; set; } = new();

    protected override void OnInitialized()
    {
        Department = CatalogService.GetDepartmentById(Id);
        if (Department is not null)
        {
            Courses = CatalogService.GetCoursesByDepartment(Department.Id);
        }
    }
}

